```yaml
name: Auto Assign Milestone

on:
  pull_request_target:
    types: [closed]
  schedule:
    - cron: '0 0 * * *' # Runs daily at midnight UTC

jobs:
  auto-assign-milestone:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout code
        uses: actions/checkout@v3

      - name: Set up .NET SDK
        uses: actions/setup-dotnet@v2
        with:
          dotnet-version: '6.0'

      - name: Install policy-bot
        run: |
          git clone https://github.com/policy-bot/policy-bot.git
          cd policy-bot
          npm install

      - name: Configure policy-bot
        run: |
          echo "module.exports = {
            rules: [
              {
                name: 'milestone-assignment',
                description: 'Assigns milestones to pull requests based on target branch',
                conditions: [
                  { type: 'pull_request', event: 'closed' }
                ],
                actions: [
                  {
                    type: 'set_milestone',
                    milestone: '${{ github.ref }}'
                  }
                ]
              }
            ]
          };" > config.js

      - name: Run policy-bot
        run: node index.js --config config.js

      - name: Update milestone on PR activity
        if: github.event_name == 'pull_request'
        run: |
          echo "module.exports = {
            rules: [
              {
                name: 'milestone-update',
                description: 'Updates milestones on PR activity',
                conditions: [
                  { type: 'pull_request', event: ['opened', 'synchronized', 'reopened', 'edited'] }
                ],
                actions: [
                  {
                    type: 'set_milestone',
                    milestone: '${{ github.ref }}'
                  }
                ]
              }
            ]
          };" > config.js
          node index.js --config config.js
```

